import json, os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'bio_0.json')
PAT = [[1,2,0,3,0,3,2,1],[2,0,3,1,3,1,0,2],[0,3,1,2,2,0,1,3],[3,1,2,0,1,2,3,0]]
units = []

def I(t, k, d, ex):
    return {"t": t, "d": d, "y": None, "yl": "", "k": k, "ex": ex}

def M(lv, q, p, c, e):
    return [lv, q, p, c, e]

def U(title, era, pre, sum_, pr, items, mcs):
    n = len(units)
    pat = PAT[n % 4]
    out = []
    for i, (lv, q, p, c, e) in enumerate(mcs):
        a = pat[i]
        ch = list(c[1:])
        ch.insert(a, c[0])
        out.append({"q": q, "p": p, "c": ch, "a": a, "e": e, "lv": lv})
    units.append({"lv": 0, "title": title, "tag": "생명", "era": era, "pre": pre, "sum": sum_,
                  "pr": [{"h": h, "b": b} for h, b in pr], "items": items, "mc": out})

